head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.vScrenID = "ULDSTF05626.xml";
scwin.pMenuID = $c.cm.InfoMenuID();
scwin.vSecugrpID = $c.lc.fn_getSecuGrpId($c.cm.InfoMenuID()); //(주권)메뉴단에서 파라미터로 받자..
scwin.vBzProcsNo = "";
scwin.vIsurCd = "";
scwin.vComNm = "";
scwin.spacYN = "N"; //기업인수목적 회사 구분
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.fr_MktId = $c.lc.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.
scwin.fr_SecuGrpId = $c.lc.fn_getSecuGrpId($c.cm.InfoMenuID()); // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 회사선택팝업에서 fr_SecuGrpId 변수를 참조. 
scwin.nColCnt = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetPar = function(arrPar) {
    // Default Get

    arrPar[0] = "";
    arrPar[1] = "";
    arrPar[2] = scwin.vSecugrpID;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetPar = function(arrPar) {
    // Default Get

    txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
    txb_COM_NM.setValue(arrPar[0].COM_NM);
};
scwin.fn_GetParModify = function(arrPar) {
    // Modify Get

    arrPar[0] = dts_List.getCellData(dts_List.getRowPosition(), "ISUR_CD");
    arrPar[1] = dts_List.getCellData(dts_List.getRowPosition(), "COM_NM");
    arrPar[2] = scwin.fr_SecuGrpId;
    arrPar[3] = scwin.fr_MktId;
    arrPar[4] = dts_List.getCellData(dts_List.getRowPosition(), "BZ_PROCS_NO");
    return arrPar.length;
};

// 
scwin.fn_GetParNew = function(arrPar) {
    // New Get
    arrPar[0] = "";
    arrPar[1] = "";
    arrPar[2] = scwin.fr_SecuGrpId;
    arrPar[3] = scwin.fr_MktId;
    arrPar[4] = "";
};


// list
scwin.fn_list_sync = function() {
    var url = "/fiscalYearChange.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01; //  01 List
    url += "&method=exstlistMarket&inputMessageId=FISCYY_CHG_INOUT&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    url += "&STYPE=1";
    url += "&BZ_SDATE=" + $c.stf.getObjectValue(edt_BzSDate);
    url += "&BZ_EDATE=" + $c.stf.getObjectValue(edt_BzEDate);
    url += "&BF_EXST_MODIFY_YN=" + $c.stf.getObjectValue(cmb_ExstModifyYN);
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
    $c.cm.ShowWin(grd_List);
    scwin.nColCnt = 1;
};


// Popup
scwin.fn_OpenPopUp = async function() {
    await $c.frame.CreateDialogFrame("ULDSTF05629.gfm", "/lstproc/ULDSTF05629.gfm", "기업인수목적회사 존립기간 변경관리", 200, 200, 665 + 2, 350, "");
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.gform_onload = function() {
    /*  Init  */
    $c.cm.PanelToGroupBox(panel_Top);

    //var vCurDate = cGetToday("yyyymmdd");
    //var vCurMonth = cGetMinusYear(vCurDate, 3);

    //edt_BzSDate.text = vCurMonth;
    //edt_BzEDate.text = vCurDate;

    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp_3);
};
scwin.txb_ISUR_CD_onblur = function() {
    /*  Keyboard Event  */
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.img_COM_NM_onclick = function() {
    /*  Button Event */
    $c.lc.fn_PopFindCorpChrgSW(scwin.vSecugrpID, "1"); // ST/ "1" : SPAC

};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.btn_New_onclick = function() {
    /* New */
    scwin.fn_GetPar = fn_GetParNew;
    scwin.fn_OpenPopUp();
};
scwin.btn_Close_onclick = async function() {
    /* Close */
    await $c.frame.CloseFrame();
};
scwin.img_Excel_onclick = function() {
    /* Save-Excel */
    if (dts_List.getTotalRow() > 0) {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, $c.lc.fn_getSecuGrpNm(scwin.vSecugrpID) + "존립기간관리목록", "", "8");
    } else {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
scwin.grd_List_OnDblClick = function(row, colid) {
    /* Grid Event - DoubleClick */
    scwin.fn_GetPar = fn_GetParModify;
    scwin.vBzProcsNo = dts_List.getCellData(row, "BZ_PROCS_NO");
    scwin.fn_OpenPopUp();
};
scwin.img_BzSDate_onclick = function() {
    popUpCalendar2(edt_BzSDate);
};
scwin.img_BzEDate_onclick = function() {
    popUpCalendar2(edt_BzEDate);
};
scwin.cmb_PeriodTp_3_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp_3, "VALUE", cmb_PeriodTp_3.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_BzSDate, edt_BzEDate);
};
scwin.grd_List_OnUserColor = function(row, eventId) {
    var colorName = "#77FF88"; //11FF00";

    //변경전 존립기간과 변경후 존립기간 변경  다른 경우 색 표시 
    if (scwin.nColCnt > 0) {
        if (eventId == "acolor7") {
            //var bfSD = dts_List.NameValue(row,"BFCHG_EXST_STRT_DD");
            var bfED = dts_List.getCellData(row, "BFCHG_EXST_END_DD");

            //var afSD = dts_List.NameValue(row,"AFCHG_EXST_STRT_DD");
            var afED = dts_List.getCellData(row, "AFCHG_EXST_END_DD");
            if (bfED != afED) {
                return colorName; // 연두색
            } else {
                if (row % 2 == 0) return "#f2f5f9";

                else return "#ffffff";
            }
        } else if (eventId == "acolor6") {
            var bfSD = dts_List.getCellData(row, "BFCHG_EXST_STRT_DD");
            var afSD = dts_List.getCellData(row, "AFCHG_EXST_STRT_DD");
            if (bfSD != afSD) {
                return colorName; // 연두색
            } else {
                if (row % 2 == 0) return "#f2f5f9";

                else return "#ffffff";
            }
        }
    }
    if (row % 2 == 0) return "#f2f5f9";

    else return "#ffffff";
};
